<script setup>
import { computed,ref } from 'vue'

const props=defineProps({apiBase:{type:String,required:true},initialToken:{type:String,default:''}})
const open=ref('list-subscribers'),token=ref(props.initialToken||''),testChannel=ref('whatsapp'),testResult=ref(''),testStatus=ref(''),testing=ref(false)

const endpoints=[
{group:'Subscribers',id:'list-subscribers',method:'GET',path:'/subscribers',title:'List subscribers',scope:'subscribers:read',desc:'List WhatsApp and Telegram subscribers visible to the API key. Filter by channel and optionally search subscriber names, usernames or identifiers.',params:[['channel','query','Optional: whatsapp or telegram'],['q','query','Optional search term'],['limit','query','Optional result limit, 1–500']],response:'{"data":[{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758","name":"Jan Venter","fields":{},"tags":[],"conversation":{"status":"resolved"}}],"count":1}',errors:'401 Invalid/revoked key · 403 Missing subscribers:read',tryable:true},
{group:'Subscribers',id:'create-subscriber',method:'POST',path:'/subscribers',title:'Create WhatsApp subscriber',scope:'subscribers:write',desc:'Create or update a WhatsApp subscriber. Telegram subscribers are created when they first interact with a connected bot.',body:'{"channel":"whatsapp","subscriber_id":"27829640758","name":"Jan Venter","fields":{},"tags":[]}',response:'{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758","name":"Jan Venter"}',errors:'401 Invalid key · 403 Missing subscribers:write · 422 Invalid data or Telegram create attempt'},
{group:'Subscribers',id:'get-subscriber',method:'GET',path:'/subscribers/{id}',title:'Get subscriber',scope:'subscribers:read',desc:'Return one subscriber including profile, custom fields, tags and current conversation state.',params:[['id','path','Canonical reference such as whatsapp:1 or telegram:27']],response:'{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758","fields":{},"tags":[],"conversation":{}}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found'},
{group:'Subscribers',id:'update-subscriber',method:'PATCH',path:'/subscribers/{id}',title:'Update subscriber profile',scope:'subscribers:write',desc:'Update supported subscriber profile properties. A canonical channel:id reference is recommended.',body:'{"name":"Updated Name"}',response:'{"id":"whatsapp:1","name":"Updated Name"}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found · 422 Invalid data'},
{group:'Subscribers',id:'delete-subscriber',method:'DELETE',path:'/subscribers/{id}',title:'Archive or remove subscriber',scope:'subscribers:write',desc:'WhatsApp subscribers are archived. Telegram subscribers are removed from WA Connect.',response:'(204 No Content)',rawResponse:true,errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found'},

{group:'Custom Fields',id:'custom-fields',method:'GET',path:'/custom-fields',title:'List custom fields',scope:'fields:read',desc:'List active custom-field definitions and stable keys. Use the channel filter when working with channel-specific workspaces.',params:[['channel','query','Optional: whatsapp or telegram']],response:'{"data":[{"id":1,"key":"company","label":"Company","type":"text","required":false}],"count":1}',errors:'401 Invalid key · 403 Missing fields:read',tryable:true},
{group:'Custom Fields',id:'subscriber-fields',method:'GET',path:'/subscribers/{id}/fields',title:'Read subscriber fields',scope:'fields:read',desc:'Read custom field values for one subscriber using stable field keys.',response:'{"subscriber":"whatsapp:1","fields":{"company":"Myself!"}}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found'},
{group:'Custom Fields',id:'set-fields',method:'PATCH',path:'/subscribers/{id}/fields',title:'Set subscriber fields',scope:'fields:write',desc:'Set one or more custom fields using stable keys rather than internal field IDs.',body:'{"fields":{"company":"Route 2 Market Solutions","order_number":"ORD-12345"}}',response:'{"subscriber":"whatsapp:1","fields":{"company":"Route 2 Market Solutions","order_number":"ORD-12345"}}',errors:'401 Invalid key · 403 Missing fields:write · 404 Subscriber not found · 422 Unknown field key'},
{group:'Custom Fields',id:'body-fields-post',method:'POST',path:'/subscribers/fields',title:'Set fields (body-first)',scope:'fields:write',desc:'Automation-friendly form that identifies the subscriber in the JSON body. Use a canonical subscriber reference, or provide channel with a numeric internal/external identifier.',body:'{"channel":"telegram","subscriber":"telegram:1","fields":{"company":"Route 2 Market Solutions","order_number":"ORD-12345"}}',response:'{"subscriber":"telegram:1","channel":"telegram","fields":{"company":"Route 2 Market Solutions","order_number":"ORD-12345"}}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found · 422 Invalid subscriber or field key'},
{group:'Custom Fields',id:'body-fields-patch',method:'PATCH',path:'/subscribers/fields',title:'Set fields (body-first PATCH)',scope:'fields:write',desc:'PATCH alias of the body-first custom-field operation for clients that prefer update semantics.',body:'{"channel":"whatsapp","subscriber":"whatsapp:1","fields":{"company":"Updated Company"}}',response:'{"subscriber":"whatsapp:1","channel":"whatsapp","fields":{"company":"Updated Company"}}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found · 422 Invalid subscriber or field key'},

{group:'Tags',id:'tags',method:'GET',path:'/tags',title:'List tags',scope:'tags:read',desc:'List tags available to the workspace/channel.',params:[['channel','query','Optional: whatsapp or telegram']],response:'{"data":[{"id":1,"name":"VIP","workspace_id":1}],"count":1}',errors:'401 Invalid key · 403 Missing tags:read',tryable:true},
{group:'Tags',id:'add-tag',method:'POST',path:'/subscribers/{id}/tags',title:'Assign or create tag',scope:'tags:write',desc:'Assign an existing tag by ID or create/assign one by name.',body:'{"name":"VIP"}',response:'{"id":1,"name":"VIP"}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found · 422 Invalid tag'},
{group:'Tags',id:'remove-tag',method:'DELETE',path:'/subscribers/{id}/tags/{tag_id}',title:'Remove tag',scope:'tags:write',desc:'Remove one tag assignment from a subscriber.',response:'(204 No Content)',rawResponse:true,errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found'},
{group:'Tags',id:'body-tags-post',method:'POST',path:'/subscribers/tags',title:'Assign tags (body-first)',scope:'tags:write',desc:'Assign one or more tags using a fixed endpoint. Tags may contain names or numeric tag IDs.',body:'{"channel":"telegram","subscriber":"telegram:1","tags":["VIP","Lead"]}',response:'{"subscriber":"telegram:1","channel":"telegram","tags":[{"id":1,"name":"VIP"},{"id":2,"name":"Lead"}]}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found · 422 No valid tags'},
{group:'Tags',id:'body-tags-patch',method:'PATCH',path:'/subscribers/tags',title:'Assign tags (body-first PATCH)',scope:'tags:write',desc:'PATCH alias of the body-first tag assignment operation.',body:'{"channel":"whatsapp","subscriber":"whatsapp:1","tags":["VIP"]}',response:'{"subscriber":"whatsapp:1","channel":"whatsapp","tags":[{"id":1,"name":"VIP"}]}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found · 422 No valid tags'},
{group:'Tags',id:'body-tags-delete',method:'DELETE',path:'/subscribers/tags',title:'Remove tags (body-first)',scope:'tags:write',desc:'Remove one or more tags using subscriber and tag values supplied in the request body.',body:'{"channel":"telegram","subscriber":"telegram:1","tags":["VIP"]}',response:'{"subscriber":"telegram:1","channel":"telegram","tags":[]}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found · 422 No valid tags'},
{group:'Tags',id:'body-tags-remove-post',method:'POST',path:'/subscribers/tags/remove',title:'Remove tags (POST compatibility)',scope:'tags:write',desc:'POST-compatible tag removal for automation clients that cannot send a JSON body with DELETE.',body:'{"channel":"whatsapp","subscriber":"whatsapp:1","tags":["VIP"]}',response:'{"subscriber":"whatsapp:1","channel":"whatsapp","tags":[]}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found · 422 No valid tags'},

{group:'Conversations & Messaging',id:'conversation',method:'PATCH',path:'/subscribers/{id}/conversation',title:'Update conversation',scope:'conversations:write',desc:'Assign an agent and/or change the latest Live Chat conversation status.',body:'{"status":"open","assigned_user_id":2}',response:'{"id":1,"status":"open","assigned_user_id":2}',errors:'401 Invalid key · 403 Missing scope · 404 Conversation not found · 422 Invalid status/agent'},
{group:'Conversations & Messaging',id:'body-conversation-post',method:'POST',path:'/subscribers/conversation',title:'Update conversation (body-first)',scope:'conversations:write',desc:'Automation-friendly conversation update with subscriber identification in the JSON body.',body:'{"channel":"telegram","subscriber":"telegram:1","status":"open","assigned_user_id":2}',response:'{"subscriber":"telegram:1","channel":"telegram","conversation":{"id":1,"status":"open","assigned_user_id":2}}',errors:'401 Invalid key · 403 Missing scope · 404 Conversation not found · 422 Invalid subscriber/status/agent'},
{group:'Conversations & Messaging',id:'body-conversation-patch',method:'PATCH',path:'/subscribers/conversation',title:'Update conversation (body-first PATCH)',scope:'conversations:write',desc:'PATCH alias of the body-first conversation update operation.',body:'{"channel":"whatsapp","subscriber":"whatsapp:1","status":"resolved"}',response:'{"subscriber":"whatsapp:1","channel":"whatsapp","conversation":{"id":1,"status":"resolved"}}',errors:'401 Invalid key · 403 Missing scope · 404 Conversation not found · 422 Invalid subscriber/status/agent'},
{group:'Conversations & Messaging',id:'send-message',method:'POST',path:'/messages/send',title:'Send text message',scope:'conversations:write',desc:'Send a free-form text message through the subscriber’s existing WhatsApp or Telegram conversation. WhatsApp free-form messages require an open customer service window; otherwise use an approved template.',body:'{"channel":"telegram","subscriber":"telegram:1","message":"Hello from WA Connect"}',response:'{"ok":true,"subscriber":"telegram:1","channel":"telegram","conversation_id":1,"message_id":42,"external_message_id":123456,"status":"sent","message":"Hello from WA Connect"}',errors:'401 Invalid key · 403 Missing conversations:write · 404 Subscriber not found · 409 No conversation/service window closed/inactive connection · 422 Invalid message · 502 Channel provider error'},

{group:'Bot Flows',id:'flows',method:'GET',path:'/bot-flows',title:'List bot flows',scope:'flows:read',desc:'List channel-targeted bot flows visible to the API key.',params:[['channel','query','Optional: whatsapp or telegram']],response:'{"data":[{"id":1,"name":"Welcome Test","channel":"whatsapp","status":"active","trigger_type":"keyword"}],"count":1}',errors:'401 Invalid key · 403 Missing flows:read',tryable:true},
{group:'Bot Flows',id:'trigger',method:'POST',path:'/bot-flows/{flow_id}/trigger',title:'Trigger bot flow',scope:'flows:trigger',desc:'Start an active WhatsApp or Telegram flow. Custom fields can be populated before execution and restart can replace an existing session.',params:[['flow_id','path','Flow ID returned by GET /bot-flows']],body:'{"subscriber":"27829640758","fields":{"order_number":"ORD-12345","campaign_source":"woocommerce"},"restart":true}',response:'{"ok":true,"flow_id":1,"flow":"Welcome Test","channel":"whatsapp","subscriber":"whatsapp:1","status":"waiting","waiting_for":"button"}',errors:'401 Invalid key · 403 Missing flows:trigger · 404 Flow/subscriber not found · 409 Inactive flow/no conversation · 422 Channel mismatch or invalid fields'},
{group:'Bot Flows',id:'reset-flow-post',method:'POST',path:'/bot-flows/reset',title:'Reset subscriber flow',scope:'flows:trigger',desc:'Return a subscriber to a neutral flow state. Resets the current flow session, cancels pending durable delays and marks active User Input submissions as reset without deleting history.',body:'{"channel":"telegram","subscriber":"telegram:1"}',response:'{"ok":true,"subscriber":"telegram:1","channel":"telegram","conversation_id":1,"previous_status":"waiting","status":"neutral","session_reset":true,"cancelled_delays":0,"reset_input_submissions":1}',errors:'401 Invalid key · 403 Missing flows:trigger · 404 Subscriber/conversation not found · 422 Invalid subscriber'},
{group:'Bot Flows',id:'reset-flow-patch',method:'PATCH',path:'/bot-flows/reset',title:'Reset subscriber flow (PATCH)',scope:'flows:trigger',desc:'PATCH alias of the flow-reset action.',body:'{"channel":"whatsapp","subscriber":"whatsapp:1"}',response:'{"ok":true,"subscriber":"whatsapp:1","channel":"whatsapp","conversation_id":1,"previous_status":"waiting","status":"neutral","session_reset":true,"cancelled_delays":0,"reset_input_submissions":0}',errors:'401 Invalid key · 403 Missing flows:trigger · 404 Subscriber/conversation not found · 422 Invalid subscriber'}
]
const groups=computed(()=>[...new Set(endpoints.map(e=>e.group))].map(name=>({name,endpoints:endpoints.filter(e=>e.group===name)})))
const methodClass=e=>e.method.toLowerCase()
function examplePath(e){return e.path.replace('{id}','whatsapp:1').replace('{tag_id}','1').replace('{flow_id}','1')}
function curlFor(e){let url=props.apiBase+examplePath(e);if(e.tryable)url+=`?channel=${testChannel.value}`;let s=`curl -sS -X ${e.method} \\\n  -H "Authorization: Bearer wac_live_YOUR_API_KEY"`;if(e.body)s+=` \\\n  -H "Content-Type: application/json"`;s+=` \\\n  "${url}"`;if(e.body)s+=` \\\n  -d '${e.body}'`;return s}
async function tryGet(e){if(!token.value.trim())return testResult.value='Enter a full wac_live_ API key first.';testing.value=true;testResult.value='';testStatus.value='';try{let url=props.apiBase+e.path+`?channel=${encodeURIComponent(testChannel.value)}`;const started=performance.now(),r=await fetch(url,{headers:{Authorization:`Bearer ${token.value.trim()}`}});const text=await r.text();testStatus.value=`HTTP ${r.status} · ${Math.round(performance.now()-started)} ms`;try{testResult.value=JSON.stringify(JSON.parse(text),null,2)}catch{testResult.value=text||'(empty response)'}}catch(err){testStatus.value='Request failed';testResult.value=err.message}finally{testing.value=false}}
</script>

<template>
<div class="docs-intro"><div><p class="eyebrow">Developer API v1</p><h2>API reference</h2><p>Workspace-scoped REST API for WhatsApp and Telegram. Every request uses a Bearer API key and the permission shown on each endpoint.</p></div><div class="auth"><b>Authorization</b><code>Bearer wac_live_…</code></div></div>
<div class="reference-note"><b>Subscriber references</b><p>Use canonical references such as <code>whatsapp:1</code> or <code>telegram:27</code> whenever possible. Body-first endpoints also accept a numeric identifier when <code>channel</code> is supplied. For WhatsApp this may resolve to the WA Connect contact ID or WhatsApp number; for Telegram it may resolve to the contact ID or Telegram user ID.</p></div>
<div class="try-card"><div><div><b>Try API</b><p>Paste a full API key for this browser session. It is not saved by WA Connect.</p></div><input v-model="token" type="password" autocomplete="off" placeholder="wac_live_…"/><select v-model="testChannel"><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option></select></div><p class="hint">Safe GET endpoints marked “Try” can be executed here. Successful requests also appear under Request Logs.</p></div>
<div class="api-groups"><section v-for="group in groups" :key="group.name" class="api-group"><header class="group-header"><div><h3>{{group.name}}</h3><p>{{group.endpoints.length}} endpoint{{group.endpoints.length===1?'':'s'}}</p></div></header><div class="api-reference"><article v-for="e in group.endpoints" :key="e.id" class="api-endpoint" :class="{expanded:open===e.id}"><button class="endpoint-summary" @click="open=open===e.id?'':e.id"><b :class="methodClass(e)">{{e.method}}</b><code>{{e.path}}</code><span>{{e.title}}</span><i>{{e.scope}}</i><em>{{open===e.id?'−':'+'}}</em></button><div v-if="open===e.id" class="endpoint-detail"><p>{{e.desc}}</p><div class="detail-grid"><section><h4>Required scope</h4><code class="scope-code">{{e.scope}}</code><template v-if="e.params"><h4>Parameters</h4><div v-for="p in e.params" :key="p[0]" class="param"><code>{{p[0]}}</code><b>{{p[1]}}</b><span>{{p[2]}}</span></div></template><template v-if="e.body"><h4>Request body</h4><pre>{{JSON.stringify(JSON.parse(e.body),null,2)}}</pre></template><h4>Errors</h4><p class="errors">{{e.errors}}</p></section><section><h4>cURL</h4><pre>{{curlFor(e)}}</pre><h4>Example response</h4><pre v-if="e.rawResponse">{{e.response}}</pre><pre v-else>{{JSON.stringify(JSON.parse(e.response),null,2)}}</pre></section></div><div v-if="e.tryable" class="try-row"><button :disabled="testing" @click="tryGet(e)">{{testing?'Running…':'▶ Try '+e.method}}</button><span>Uses {{testChannel}} channel</span></div><div v-if="e.tryable&&testResult" class="try-result"><b>{{testStatus}}</b><pre>{{testResult}}</pre></div></div></article></div></section></div>
</template>

<style scoped>
