x;padding:5px 6px;text-align:center;background:#e9f6ef;color:#168452}.endpoint-summary>b.post{background:#e9f1fb;color:#316aa0}.endpoint-summary>b.patch{background:#fff4df;color:#936a18}.endpoint-summary>b.delete{background:#faecec;color:#a33}.endpoint-summary>span{font-weight:700;color:#294238}.endpoint-summary>i{font-style:normal;font-size:10px;color:#628074;background:#f0f5f2;padding:4px 7px;border-radius:999px;width:max-content}.endpoint-summary>em{font-style:normal;font-size:20px;color:#188451}.endpoint-detail{border-top:1px solid #edf1ef;padding:17px 18px;background:#fbfdfc}.endpoint-detail>p{color:#667c72;margin:0 0 15px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.detail-grid section{min-width:0}.detail-grid h4{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#61766c;margin:14px 0 7px}.detail-grid h4:first-child{margin-top:0}.scope-code{display:inline-block;background:#e9f6ef;color:#117947;padding:5px 8px;border-radius:6px}.detail-grid pre,.try-result pre{white-space:pre-wrap;word-break:break-word;background:#102c21;color:#dcf4e8;padding:12px;border-radius:8px;font-size:11px;line-height:1.45;max-height:330px;overflow:auto}.param{display:grid;grid-template-columns:120px 55px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid #edf1ef;font-size:11px}.param b{text-transform:uppercase;color:#799087;font-size:9px}.errors{font-size:11px;color:#8c5959!important}.try-row{display:flex;align-items:center;gap:10px;margin-top:14px;border-top:1px solid #e6eeea;padding-top:14px}.try-row button{border:0;background:#13a65b;color:#fff;border-radius:8px;padding:9px 13px;font-weight:800;cursor:pointer}.try-row button:disabled{opacity:.5}.try-row span{font-size:11px;color:#71847a}.try-result{margin-top:12px}.try-result>b{font-size:11px;color:#167d4d}.try-result pre{margin-bottom:0}@media(max-width:1100px){.endpoint-summary{grid-template-columns:62px 1fr 24px}.endpoint-summary>span{grid-column:2}.endpoint-summary>i{display:none}.detail-grid{grid-template-columns:1fr}.try-card>div{grid-template-columns:1fr}.auth{display:none}}
</style>
